function greet() {
  console.log('Hello, world!');
}
greet(); // Calls the function and prints 'Hello, world!'

function greet(name) {
  console.log('Hello, ' + name + '!');
}
greet('Alice'); // Prints 'Hello, Alice!'

function add(a, b) {
  return a + b;
}
let sum = add(5, 7);
console.log(sum); // 12

const multiply = function(x, y) {
  return x * y;
};
console.log(multiply(3, 4)); // 12

const square = (n) => n * n;
console.log(square(5)); // 25
// Arrow functions offer a concise syntax for writing functions.

function checkAge(age) {
  if (age >= 18) {
    return 'Adult';
  } else {
    return 'Minor';
  }
}
console.log(checkAge(20)); // 'Adult'

for (let i = 1; i <= 5; i++) {
  console.log('Count: ' + i);
}
